const items = [
  { name: 'Tea', price: 40, qty: 2 },
  { name: 'Cake', price: 120, qty: 1 },
  { name: 'Water', price: 20, qty: 0 },
];

const names = items.map((item) => item.name);
const inCart = items.filter((item) => item.qty > 0);
const total = items.reduce((sum, item) => sum + item.price * item.qty, 0);

console.log(names);           // ['Tea', 'Cake', 'Water']
console.log(inCart.length);   // 2
console.log(total);           // 200

const votes = ['tea', 'coffee', 'tea', 'juice', 'tea'];

const tally = votes.reduce((counts, drink) => {
  counts[drink] = (counts[drink] ?? 0) + 1;
  return counts;
}, {});

console.log(tally); // { tea: 3, coffee: 1, juice: 1 }

