const original = {
  name: 'Report',
  createdAt: new Date('2026-01-15T00:00:00Z'),
  tags: ['a', undefined, 'b'],
  notes: undefined,
  ratio: NaN,
  render() { return 'x'; },
};

const text = JSON.stringify(original);
console.log(text);
// {"name":"Report","createdAt":"2026-01-15T00:00:00.000Z","tags":["a",null,"b"],"ratio":null}

const copy = JSON.parse(text);
console.log(typeof copy.createdAt); // 'string'
console.log('notes' in copy);       // false

function parseReport(text) {
  try {
    return JSON.parse(text, (key, value) =>
      key === 'createdAt' ? new Date(value) : value
    );
  } catch {
    return null;
  }
}

console.log(parseReport('{"createdAt":"2026-01-15T00:00:00.000Z"}').createdAt instanceof Date); // true
console.log(parseReport('{not json'));  // null

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

function parseQuantity(input) {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 1) {
    throw new ValidationError(`Invalid quantity: ${input}`);
  }
  return n;
}

for (const input of ['3', 'many']) {
  try {
    console.log('parsed', parseQuantity(input));
  } catch (error) {
    if (error instanceof ValidationError) console.log(error.name, '-', error.message);
    else throw error;
  } finally {
    console.log('done with', input);
  }
}

function loadSettings(text) {
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error('Settings file is corrupt', { cause: error });
  }
}

try {
  loadSettings('{oops');
} catch (error) {
  console.log(error.message);       // 'Settings file is corrupt'
  console.log(error.cause.name);    // 'SyntaxError'
}
